/**
 * Harness ToolDescriptor types — generic projection of the backend
 * `ToolDescriptor` declaration.
 *
 * Tool exposure, catalog display, approval, and redaction are generated by the
 * backend registry; the UI renders these fields without a per-tool event
 * allowlist. Never pass free-form tool output through `unsafeHTML`/`innerHTML`.
 */

export type ToolEffectKind = "read" | "write" | "destructive" | "external";

export type ToolCapability = "vision" | "video" | "audio" | "network" | "text";

/** Generic display metadata declared by the tool. */
export interface ToolPresentation {
  label: string;
  group: string;
  groupLabel: string;
  danger: boolean;
  enabled: boolean;
  icon?: string | null;
}

/** Catalog entry produced by `GET /tools/catalog`. */
export interface ToolCatalogEntry extends ToolPresentation {
  id: string;
  name: string;
  description: string;
  effectKind: ToolEffectKind;
  requiresApproval: boolean;
  requiredCapabilities: ToolCapability[];
}

export interface ToolCatalogGroup {
  id: string;
  label: string;
  source: string;
  tools: ToolCatalogEntry[];
}

export interface ToolCatalog {
  groups: ToolCatalogGroup[];
}

/** Effective approval policy after the Workflow policy tightened the tool. */
export interface ToolApprovalPolicy {
  mandatory: boolean;
  timeoutSecs: number;
  reason?: string | null;
}

/** Public, secret-redacted tool-call metadata (never raw request JSON). */
export interface ToolCallMetadata {
  toolName: string;
  argumentsSummary: string;
  presentation?: ToolPresentation;
  requiredCapabilities: ToolCapability[];
  approval: ToolApprovalPolicy;
}
